const parts = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Asia/Singapore',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
}).formatToParts(new Date());

const today = `${parts.find(p => p.type === 'year').value}-${parts.find(p => p.type === 'month').value}-${parts.find(p => p.type === 'day').value}`;

const d = new Date(`${today}T00:00:00+08:00`);
d.setDate(d.getDate() - 370);
const startDate = d.toISOString().slice(0, 10);

return [{
  json: {
    today_sgt: today,
    start_date: startDate,
    horizons: [1, 5, 10, 20],
    note: 'Manual validation backtest only. Python remains the primary backtest and portfolio engine.'
  }
}];

const out = [];

for (const item of $input.all()) {
  if (Array.isArray(item.json)) out.push(...item.json);
  else if (Array.isArray(item.json?.data)) out.push(...item.json.data);
  else if (Array.isArray(item.json?.rows)) out.push(...item.json.rows);
  else out.push(item.json);
}

return [{
  json: {
    today_sgt: $('Build Backtest Params').first().json.today_sgt,
    start_date: $('Build Backtest Params').first().json.start_date,
    horizons: $('Build Backtest Params').first().json.horizons,
    score_rows: out
  }
}];

const toNum = v => {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
};

const round2 = v => {
  if (v === null || v === undefined || !Number.isFinite(v)) return null;
  return Math.round(v * 100) / 100;
};

const flatten = items => {
  const out = [];
  for (const item of items) {
    if (Array.isArray(item.json)) out.push(...item.json);
    else if (Array.isArray(item.json?.data)) out.push(...item.json.data);
    else if (Array.isArray(item.json?.rows)) out.push(...item.json.rows);
    else out.push(item.json);
  }
  return out;
};

const params = $('Build Backtest Params').first().json;
const horizons = Array.isArray(params.horizons) ? params.horizons : [1, 5, 10, 20];

const scoreRows = $('Wrap Score Rows').first().json.score_rows || [];
const rawPriceRows = flatten($input.all());

const priceMap = {};
for (const r of rawPriceRows) {
  if (!r || !r.metric_date || !r.ticker) continue;
  const ticker = String(r.ticker).toUpperCase();
  const date = String(r.metric_date);
  const price = toNum(r.latest_price);
  if (price === null) continue;
  priceMap[`${ticker}||${date}`] = { ticker, date, price };
}

const pricesByTicker = {};
for (const p of Object.values(priceMap)) {
  if (!pricesByTicker[p.ticker]) pricesByTicker[p.ticker] = [];
  pricesByTicker[p.ticker].push(p);
}

for (const ticker of Object.keys(pricesByTicker)) {
  pricesByTicker[ticker].sort((a, b) => a.date.localeCompare(b.date));
}

const scoreMap = {};
for (const s of scoreRows) {
  if (!s || !s.run_date_sgt || !s.ticker) continue;
  if (toNum(s.overall_ai_risk_score) === null) continue;

  const ticker = String(s.ticker).toUpperCase();
  const date = String(s.run_date_sgt);
  scoreMap[`${date}||${ticker}`] = { ...s, ticker, run_date_sgt: date };
}

const cleanScoreRows = Object.values(scoreMap)
  .sort((a, b) => String(a.run_date_sgt).localeCompare(String(b.run_date_sgt)));

function findEntryIndex(arr, signalDate) {
  let idx = arr.findIndex(p => p.date === signalDate);
  if (idx >= 0) return idx;
  return arr.findIndex(p => p.date > signalDate);
}

const results = [];

for (const s of cleanScoreRows) {
  const ticker = String(s.ticker).toUpperCase();
  const prices = pricesByTicker[ticker] || [];
  if (!prices.length) continue;

  const entryIdx = findEntryIndex(prices, s.run_date_sgt);
  if (entryIdx < 0) continue;

  const entry = prices[entryIdx];
  if (!entry || !entry.price) continue;

  for (const h of horizons) {
    const horizon = Number(h);
    const exitIdx = entryIdx + horizon;
    if (exitIdx >= prices.length) continue;

    const exit = prices[exitIdx];
    if (!exit || !exit.price) continue;
    if (exit.date <= entry.date) continue;

    const window = prices
      .slice(entryIdx, exitIdx + 1)
      .map(p => p.price)
      .filter(v => v !== null);

    const minPrice = window.length ? Math.min(...window) : null;

    const forwardReturnPct = ((exit.price / entry.price) - 1) * 100;
    const maxDrawdownPct = minPrice !== null ? ((minPrice / entry.price) - 1) * 100 : null;

    results.push({
      signal_date_sgt: s.run_date_sgt,
      ticker,
      horizon_days: horizon,
      signal_label: s.signal_label || null,
      valuation_score: round2(toNum(s.valuation_score)),
      momentum_score: round2(toNum(s.momentum_score)),
      overheating_score: round2(toNum(s.overheating_score)),
      overall_ai_risk_score: round2(toNum(s.overall_ai_risk_score)),
      momentum_change_5d: round2(toNum(s.momentum_change_5d)),
      reversal_score: round2(toNum(s.reversal_score)),
      reversal_signal: Boolean(s.reversal_signal),
      entry_date: entry.date,
      entry_price: round2(entry.price),
      exit_date: exit.date,
      exit_price: round2(exit.price),
      forward_return_pct: round2(forwardReturnPct),
      max_drawdown_pct: round2(maxDrawdownPct),
      source: 'n8n_manual_validation_backtest'
    });
  }
}

const chunkSize = 500;
const chunks = [];

for (let i = 0; i < results.length; i += chunkSize) {
  chunks.push({
    json: {
      rows: results.slice(i, i + chunkSize),
      row_count: Math.min(chunkSize, results.length - i),
      debug_score_rows: cleanScoreRows.length,
      debug_price_rows_raw: rawPriceRows.length,
      debug_price_rows_deduped: Object.values(priceMap).length,
      debug_backtest_rows: results.length
    }
  });
}

return chunks.length ? chunks : [{
  json: {
    rows: [],
    row_count: 0,
    debug_score_rows: cleanScoreRows.length,
    debug_price_rows_raw: rawPriceRows.length,
    debug_price_rows_deduped: Object.values(priceMap).length,
    debug_backtest_rows: 0,
    note: 'No completed backtest rows available yet.'
  }
}];
